(()=>{'use strict';const imagePath=/\.(?:avif|bmp|gif|jpe?g|png|svg|webp)(?:[?#].*)?$/i;function imageLink(e){const a=e.target.closest?.('a[href]');return a&&imagePath.test(a.getAttribute('href')||'')?a:null}document.addEventListener('contextmenu',e=>{if(e.target.closest?.('img,picture')||imageLink(e))e.preventDefault()});document.addEventListener('dragstart',e=>{if(e.target.closest?.('img,picture')||imageLink(e))e.preventDefault()});document.addEventListener('auxclick',e=>{if(imageLink(e))e.preventDefault()});document.addEventListener('click',e=>{const a=imageLink(e);if(!a)return;e.preventDefault();if(e.button!==0)return;const dialog=document.createElement('dialog');dialog.className='protected-image-viewer';dialog.setAttribute('aria-label','عرض الصورة');const close=document.createElement('button');close.type='button';close.textContent='×';close.setAttribute('aria-label','إغلاق');const img=document.createElement('img');img.src=a.href;img.alt=a.textContent.trim()||'صورة';img.draggable=false;dialog.append(close,img);document.body.append(dialog);close.onclick=()=>dialog.close();dialog.addEventListener('click',ev=>{if(ev.target===dialog)dialog.close()});dialog.addEventListener('close',()=>dialog.remove());dialog.showModal()},true)})();
